#!/usr/bin/env bash
# larch-log-batches.sh — canonical larch-log batch table.

set -euo pipefail

LARCH_LOG_BATCHES="
plan-goals-test .md replace none
plan-review-tally .ndjson append none
code-review-tally .ndjson append none
review-findings-full .ndjson append none
review-context .md replace none
review-findings .ndjson append none
review-panel-manifest .ndjson replace none
review-round-summary .md replace none
review-tally .md replace none
version-bump-reasoning .md replace none
oos-issues .ndjson append none
run-statistics .md replace none
token-report .md replace none
timing-report .md replace none
execution-issues .ndjson append none
session-transcript .jsonl replace none
"

larch_log_batch_info() {
    local slug="$1"
    printf '%s\n' "$LARCH_LOG_BATCHES" | awk -v slug="$slug" '
        NF == 4 && $1 == slug { print $2 " " $3 " " $4; found = 1 }
        END { if (!found) exit 1 }
    '
}

larch_log_batch_extension() {
    larch_log_batch_info "$1" | awk '{ print $1 }'
}

larch_log_batch_mode() {
    larch_log_batch_info "$1" | awk '{ print $2 }'
}

larch_log_batch_sanitizer() {
    larch_log_batch_info "$1" | awk '{ print $3 }'
}

larch_log_batch_list() {
    printf '%s\n' "$LARCH_LOG_BATCHES" | awk 'NF == 4 { print $1 }'
}

#!/usr/bin/env bash
# append-execution-issue.sh — append a categorized execution issue entry.

set -euo pipefail

fail_usage() {
    echo "FAILED=true"
    echo "ERROR=usage: $1"
    exit 1
}

LOG_FILE=""
CATEGORY=""
ENTRY=""

while [ $# -gt 0 ]; do
    case "$1" in
        --log)
            [ $# -ge 2 ] || fail_usage "--log requires a value"
            LOG_FILE="$2"; shift 2 ;;
        --category)
            [ $# -ge 2 ] || fail_usage "--category requires a value"
            CATEGORY="$2"; shift 2 ;;
        --entry)
            [ $# -ge 2 ] || fail_usage "--entry requires a value"
            ENTRY="$2"; shift 2 ;;
        *)
            fail_usage "unknown flag: $1" ;;
    esac
done

[ -n "$LOG_FILE" ] || fail_usage "--log is required"
[ -n "$CATEGORY" ] || fail_usage "--category is required"
[ -n "$ENTRY" ] || fail_usage "--entry is required"

case "$CATEGORY" in
    "Pre-existing Code Issues"|"Tool Failures"|"Permission Prompts"|"External Reviewer Issues"|"CI Issues"|"Warnings"|"Q/A") ;;
    *) fail_usage "unsupported category: $CATEGORY" ;;
esac

mkdir -p "$(dirname "$LOG_FILE")" 2>/dev/null || {
    echo "FAILED=true"
    echo "ERROR=cannot create log parent: $(dirname "$LOG_FILE")"
    exit 2
}

if [ ! -f "$LOG_FILE" ]; then
    : > "$LOG_FILE" || {
        echo "FAILED=true"
        echo "ERROR=cannot create log: $LOG_FILE"
        exit 2
    }
fi

tmp="$(mktemp "${LOG_FILE}.XXXXXX")" || {
    echo "FAILED=true"
    echo "ERROR=cannot create temp file next to log"
    exit 2
}
trap 'rm -f "$tmp"' EXIT

awk -v category="$CATEGORY" -v entry="$ENTRY" '
    BEGIN {
        header = "### " category
        found = 0
        inserted = 0
    }
    $0 == header {
        found = 1
        in_target = 1
        print
        next
    }
    in_target && /^### / {
        if (!inserted) {
            print ""
            print entry
            inserted = 1
        }
        in_target = 0
    }
    { print }
    END {
        if (found && !inserted) {
            print ""
            print entry
        } else if (!found) {
            if (NR > 0) print ""
            print header
            print ""
            print entry
        }
    }
' "$LOG_FILE" > "$tmp" || {
    echo "FAILED=true"
    echo "ERROR=failed to update log: $LOG_FILE"
    exit 2
}

mv -f "$tmp" "$LOG_FILE" || {
    echo "FAILED=true"
    echo "ERROR=failed to move log into place: $LOG_FILE"
    exit 2
}
trap - EXIT

echo "APPENDED=true"
echo "LOG=$LOG_FILE"
exit 0

SOURCE_FILE=""
LOG_ROOT=""
SKILL=""
RUN_ID=""
NO_LOGS_COMMIT=""
EXECUTION_ISSUES_LOG=""

while [ $# -gt 0 ]; do
    case "$1" in
        --source-file)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            SOURCE_FILE="$2"; shift 2 ;;
        --log-root)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            LOG_ROOT="$2"; shift 2 ;;
        --skill)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            SKILL="$2"; shift 2 ;;
        --run-id)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            RUN_ID="$2"; shift 2 ;;
        --no-logs-commit)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            NO_LOGS_COMMIT="$2"; shift 2 ;;
        --execution-issues-log)
            [ $# -ge 2 ] || { usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0; }
            EXECUTION_ISSUES_LOG="$2"; shift 2 ;;
        *) usage; echo "SESSION_TRANSCRIPT_STATUS=usage-error"; exit 0 ;;
    esac
done

append_warning() {
    local status="$1"
    local message="$2"

    [ -n "$EXECUTION_ISSUES_LOG" ] || return 0
    "$SCRIPT_DIR/append-execution-issue.sh" \
        --log "$EXECUTION_ISSUES_LOG" \
        --category Warnings \
        --entry "- **Step 18 — session-transcript status=$status:** $message" \
        >/dev/null 2>&1 || true
}

emit_status() {
    local status="$1"
    local message="$2"

    append_warning "$status" "$message"
    echo "SESSION_TRANSCRIPT_STATUS=$status"
    exit 0
}

if [ -z "$SOURCE_FILE" ] || [ ! -f "$SOURCE_FILE" ]; then
    emit_status "source-file-missing" "Claude source file was empty or not a regular file; transcript capture skipped."
fi

TRANSCRIPT_PATH="$(awk 'BEGIN{prefix="TRANSCRIPT_PATH="} index($0, prefix) == 1 {print substr($0, length(prefix) + 1); exit}' "$SOURCE_FILE" 2>/dev/null || true)"
if [ -z "$TRANSCRIPT_PATH" ]; then
    emit_status "transcript-path-missing" "Claude source file did not contain a TRANSCRIPT_PATH entry; transcript capture skipped."

